/** Any stored/AI/picker category value -> canonical path, or null. */
export function resolveCategory(raw) {
  if (typeof raw !== 'string') return null;
  const v = raw.trim().replace(/^\/+/, '').replace(/\s*\/\s*/g, '/');
  if (!v) return null;
  // exact canonical path, any capitalisation
  for (const p of PATHS) if (p.toLowerCase() === v.toLowerCase()) return p;
  const legacy = LEGACY[v.toLowerCase()];
  if (legacy) return legacy;
  // 'Dept/Sub' where only the department is known -> leave the department
  // alone rather than nulling it: a partially-filed item is still findable.
  const parts = v.split('/');
  const dept = DEPARTMENTS.find((d) => d.toLowerCase() === parts[0].toLowerCase());
  if (!dept) return null;
  if (parts.length === 1) return dept;
  const sub = parts.slice(1).join('/');
  const under = paths.find((p) => p.toLowerCase() === (dept + '/' + sub).toLowerCase());
  if (under) return under;
  const sameSub = paths.find((p) => {
    const ps = p.split('/');
    return ps[0] === dept && ps.slice(1).join('/').toLowerCase() === sub.toLowerCase();
  });
  return sameSub || dept;
}

/* The market route pre-filters in SQL against the raw column, which still
   holds the old spellings for rows written before this table existed.
   Resolve the request into a small set of PREFIXES and let SQL LIKE each
   one, rather than enumerate every spelling that maps to the same place.
   Two reasons, both load-bearing:
     • a bare department has to reach rows stored as "Women's Clothing/…"
       and "Bags & Luggage/Handbags", which are not under it by string;
     • enumerating them would put ~126 values in the WHERE clause, and D1
       caps a statement at 100 bound parameters — so the query would 500
       on the busiest click in the shop, which is worse than an empty page.
   Prefixes can over-match ("women's clothing" also covers a sub-category
       that belongs elsewhere), so the route applies belongsUnder() to the
       canonicalized row afterwards. Over-matching is then harmless; under-
       matching is what made a department click return nothing at all. */

/**
 * LIKE prefixes that cover every value belonging under a requested place
 * in the tree.
 *
 * BOTH heads and full legacy paths are needed, and that is not belt-and-
 * braces — a legacy SUB-path resolves differently from its own head:
 *   resolveCategory("men's clothing")         -> "Men/Tops"
 *   resolveCategory("men's clothing/outerwear") -> "Men/Coats & Jackets"
 * So a request for "Men/Coats & Jackets" that only considered heads would
 * drop "men's clothing" (nothing under it belongs here) and then fail to
 * LIKE-match the row actually stored as "Men's Clothing/Outerwear" — the
 * item would be missing from its own leaf. Full paths close that.
 *
 * Prefixes can over-match ("women's clothing" also covers a sub-category
 * that belongs elsewhere), so the route applies belongsUnder() to the
 * canonicalized row afterwards. Over-matching is then harmless; under-
 * matching is what made a department click return nothing at all. */
export function prefixesFor(raw) {
  const path = resolveCategory(raw);
  if (!path) return [];
  const under = (r) => r === path || r.startsWith(path + '/') || path.startsWith(r + '/');
  const out = new Set([path]);
  for (const key of Object.keys(LEGACY)) {
    const r = resolveCategory(key);
    if (r && under(r)) out.add(key);
  }
  return [...out];
}

/**
 * The authoritative test, applied to the canonicalized row after the fetch.
 * SQL decides what to look at; this decides what is actually under the
 * click. A bare department means everything filed beneath it.
 *
 * `requestedPath` is the ALREADY-RESOLVED path, and passing null means
 * "the request named no place in the table", which matches nothing. That
 * direction is deliberate: a department a shopper asked for and nothing
 * answers to must come back empty, not full. Returning everything would
 * mean a typo in a URL silently shows the entire shop under the wrong
 * heading, which is worse than an empty page because nobody notices. */
export function belongsUnder(rowCategory, requestedPath) {
  if (!requestedPath) return false;
  const got = resolveCategory(rowCategory);
  if (!got) return false;
  return got === requestedPath || got.startsWith(requestedPath + '/');
}
